def chain_follows_chain(WELL_FORMED):
    chain = []
    for token in WELL_FORMED:
        if token == 'a':
            chain.append('a')
        else:
            chain.append(token)

    # Find the first token that is not 'a'
    for i in range(len(chain)):
        if chain[i] != 'a':
            break
    else:
        # If all tokens are 'a', the chain is a single token
        return chain
